// Copyright 2026 Query Farm LLC - https://query.farm

// Command vgi-media-worker is a VGI worker that extracts video / audio /
// container metadata from media files via ffprobe (part of ffmpeg) and exposes
// it as DuckDB SQL scalar and table functions. It speaks the VGI protocol over
// stdio.
//
// ffprobe is a heavyweight NATIVE dependency: it must be installed separately
// (e.g. `brew install ffmpeg`) and available on PATH. The worker only EXECs the
// ffprobe binary in a subprocess; it does not link any ffmpeg library.
package main

import (
	"flag"
	"log"
	"os"
	"strings"

	"github.com/Query-farm/vgi-go/vgi"
	"github.com/Query-farm/vgi-media/internal/mediaworker"
)

func main() {
	// Accept --http for HTTP transport and --unix for the AF_UNIX launcher
	// transport; default is stdio. Unknown launcher flags are tolerated (the
	// VGI extension varies argv to key its worker cache), so we filter to flags
	// we actually define before parsing.
	httpMode := flag.Bool("http", false, "Run as an HTTP server instead of stdio")
	httpAddr := flag.String("http-addr", "127.0.0.1:0", "HTTP listen address (ignored unless --http); default binds an ephemeral loopback port for dev/CI")
	unixPath := flag.String("unix", "", "Serve the AF_UNIX launcher transport on this socket path instead of stdio")
	logFlags := vgi.RegisterLoggingFlags(flag.CommandLine)
	_ = flag.CommandLine.Parse(filterKnownFlags(os.Args[1:], map[string]bool{
		"log-level":  true,
		"log-format": true,
		"log-logger": true,
		"http-addr":  true,
		"unix":       true,
	}))
	if err := logFlags.Apply(); err != nil {
		log.Fatalf("logging flags: %v", err)
	}

	sourceURL := "https://github.com/Query-farm/vgi-media"
	w := vgi.NewWorker(
		vgi.WithCatalogName(mediaworker.CatalogName),
		vgi.WithCatalogComment("Extract video/audio/container metadata from media files via ffprobe."),
		vgi.WithCatalogInfo(vgi.CatalogInfo{
			Name:      mediaworker.CatalogName,
			SourceURL: &sourceURL,
		}),
		vgi.WithCatalogTags(map[string]string{
			"source":       "vgi-media",
			"vgi.title":    "Media Metadata",
			"vgi.subtitle": "Query codec, resolution, duration, bitrate, streams, and tags of video and audio files with ffprobe.",
			"vgi.keywords": `["media","video","audio","ffprobe","ffmpeg","metadata","codec",` +
				`"duration","bitrate","resolution","fps","streams","container format",` +
				`"mp4","mkv","wav","transcoding"]`,
			"vgi.doc_llm": "Extract video, audio, and container metadata from media files " +
				"with ffprobe (ffmpeg). Scalars take a file path (`VARCHAR`) or media bytes (`BLOB`) and " +
				"return container format, duration, bit rate, size, stream count, and per-stream video " +
				"(codec, width, height, resolution, fps) and audio (codec) attributes. Table functions " +
				"list every elementary stream (media_streams) and every format-level metadata tag " +
				"(media_tags). Use for media inventory, transcoding triage, and quality/conformance checks in SQL.",
			"vgi.doc_md": "# Media Metadata Extraction in SQL with ffprobe\n\n" +
				"![FFmpeg logo](https://ffmpeg.org/ffmpeg-logo.png)\n\n" +
				"Inspect video, audio, and container files directly from DuckDB SQL: read codec, " +
				"resolution, duration, bitrate, frame rate, and embedded metadata tags from MP4, MKV, " +
				"MOV, WAV, MP3, WebM, and every other format that [FFmpeg](https://ffmpeg.org) can " +
				"open — no manual transcoding, no external scripts.\n\n" +
				"This extension is for data engineers, media pipelines, and anyone who needs to take " +
				"inventory of a media library, triage transcoding jobs, or run quality and conformance " +
				"checks at scale. Instead of shelling out to a command-line tool and parsing JSON by " +
				"hand, you query your media the same way you query any other table, and join the results " +
				"against the rest of your warehouse.\n\n" +
				"## How it works\n\n" +
				"Under the hood the worker runs [ffprobe](https://ffmpeg.org/ffprobe.html), the media " +
				"analyzer that ships with the [FFmpeg](https://github.com/FFmpeg/FFmpeg) project, in a " +
				"sandboxed subprocess with bounded probe size and timeouts so that truncated or " +
				"untrusted bytes can never hang a query. Every function accepts either a filesystem " +
				"path (`VARCHAR`) or the raw media bytes (`BLOB`), so you can probe files on disk or `BLOB` " +
				"columns already loaded into DuckDB. ffprobe's findings are surfaced over Apache Arrow " +
				"as native SQL columns; missing or unparseable fields return NULL rather than erroring.\n\n" +
				"## What you can read\n\n" +
				"The worker groups its surface into a few kinds of reading:\n\n" +
				"- **Container-level facts** — one value per file, such as the format name, playback " +
				"duration, overall bit rate, byte size, and how many elementary streams the file holds.\n" +
				"- **Video attributes** — for the first video track: its codec, pixel width and height, " +
				"a combined resolution string, and the average frame rate.\n" +
				"- **Audio attributes** — for the first audio track, such as its codec.\n" +
				"- **Full enumeration** — table functions that return one row per elementary stream, " +
				"and one row per format-level metadata tag, when you need every detail rather than a " +
				"single summary value.\n\n" +
				"## When to use it\n\n" +
				"Reach for this worker whenever media files are part of your data and you want their " +
				"technical metadata available in SQL: cataloguing an asset library, validating that " +
				"uploads meet a resolution or codec policy, or driving transcoding decisions from a " +
				"query rather than a bespoke script.\n\n" +
				"See the official [ffprobe documentation](https://ffmpeg.org/ffprobe.html) and the " +
				"broader [FFmpeg documentation](https://ffmpeg.org/documentation.html) for details on " +
				"the underlying analyzer.",
			// Fixed analyst-task suite (VGI152/VGI920). Built at runtime so the
			// prompts point at the committed fixture's absolute path wherever the
			// worker is launched from; the graders live in vgi-agent-tests.yaml.
			"vgi.agent_test_tasks":   mediaworker.AgentTestTasksJSON(),
			"vgi.author":             "Query.Farm",
			"vgi.copyright":          "Copyright 2026 Query Farm LLC - https://query.farm",
			"vgi.license":            "MIT",
			"vgi.support_contact":    "https://github.com/Query-farm/vgi-media/issues",
			"vgi.support_policy_url": "https://github.com/Query-farm/vgi-media/blob/main/README.md",
		}),
		vgi.WithSchemaComments(map[string]string{
			"main": "Media metadata extraction functions (scalars + table functions) over ffprobe.",
		}),
		vgi.WithSchemaTags(map[string]map[string]string{
			"main": {
				"vgi.title": "Media Functions",
				"vgi.keywords": `["media","video","audio","ffprobe","metadata","codec",` +
					`"duration","bitrate","resolution","fps","media_streams","media_tags",` +
					`"container format"]`,
				// VGI123 classifying tags use BARE keys (not vgi.-namespaced) so the
				// schema is findable by facet/topic.
				"domain":   "media",
				"category": "metadata-extraction",
				"topic":    "video-audio-inspection",
				"vgi.doc_llm": "Media metadata functions: container-level scalars (format, " +
					"duration, bitrate, size, stream_count), per-stream video/audio scalars (codec, " +
					"width, height, resolution, fps), and table functions for elementary streams " +
					"(media_streams) and format-level metadata tags (media_tags).",
				"vgi.doc_md": "## Media metadata functions\n\n" +
					"Read technical metadata from video, audio, and container files over Apache Arrow, " +
					"backed by ffprobe. Every function accepts either a media file path (`VARCHAR`) or " +
					"the raw media bytes (`BLOB`), and missing or unparseable fields return NULL rather " +
					"than erroring.\n\n" +
					"The surface is organised into a few groups:\n\n" +
					"- **Container** — one value per file: format, duration, bit rate, size, and " +
					"stream count.\n" +
					"- **Video** — the first video track's codec, width, height, resolution, and " +
					"frame rate.\n" +
					"- **Audio** — the first audio track's codec.\n" +
					"- **Enumeration** — table functions that return one row per elementary stream and " +
					"one row per format-level metadata tag.\n\n" +
					"Use this schema for media inventory, transcoding triage, and quality or " +
					"conformance checks in SQL.",
				// Navigation/SEO category registry (VGI413) — each function/table
				// below is filed into one of these via a vgi.category tag.
				"vgi.categories": `[` +
					`{"name":"container","description":"Container-level facts about a media file: format name, duration, bit rate, byte size, and elementary-stream count."},` +
					`{"name":"video","description":"Attributes of the first video stream: codec, pixel width and height, resolution string, and average frame rate."},` +
					`{"name":"audio","description":"Attributes of the first audio stream, such as its codec name."},` +
					`{"name":"enumeration","description":"Table functions that enumerate every elementary stream and every format-level metadata tag in a file."},` +
					`{"name":"discovery","description":"Browsable registry view of the catalog's media functions, so an agent can discover every callable object and its result type without first probing a file."}` +
					`]`,
				// VGI506/VGI515 representative, described example queries for the
				// schema. Built at runtime so each query points at the committed
				// fixture and executes cleanly with real rows.
				"vgi.example_queries": mediaworker.SchemaExampleQueriesJSON(),
			},
		}),
	)
	mediaworker.Register(w)

	if *httpMode {
		if err := w.RunHttp(*httpAddr); err != nil {
			log.Fatal(err)
		}
		return
	}
	if *unixPath != "" {
		// AF_UNIX launcher transport: serve on the given socket path. The SDK
		// prints "UNIX:<path>" once listening; idleTimeout=0 disables the
		// self-shutdown timer (the launcher/CI owns the process lifecycle).
		if err := w.RunUnix(*unixPath, 0); err != nil {
			log.Fatal(err)
		}
		return
	}
	w.RunStdio()
}

// filterKnownFlags drops argv tokens for flags this binary doesn't define, so
// launcher-injected differentiation flags don't abort flag parsing. Flags named
// in valueFlags consume the following token as their value.
func filterKnownFlags(args []string, valueFlags map[string]bool) []string {
	defined := map[string]bool{}
	flag.CommandLine.VisitAll(func(f *flag.Flag) { defined[f.Name] = true })
	var out []string
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !strings.HasPrefix(a, "-") {
			continue
		}
		name := strings.TrimLeft(a, "-")
		hasInlineValue := strings.ContainsRune(name, '=')
		if eq := strings.IndexByte(name, '='); eq >= 0 {
			name = name[:eq]
		}
		if !defined[name] {
			continue
		}
		out = append(out, a)
		if valueFlags[name] && !hasInlineValue && i+1 < len(args) {
			i++
			out = append(out, args[i])
		}
	}
	return out
}

registration.internal/mediaworker/scalars.go:
// Copyright 2026 Query Farm LLC - https://query.farm

package mediaworker

import (
	"context"

	"github.com/Query-farm/vgi-go/vgi"
	"github.com/apache/arrow-go/v18/arrow"
	"github.com/apache/arrow-go/v18/arrow/array"
)

// inputArg is the shared single-argument struct for every scalar. The input is
// a column arg (`const=false`) declared as arrow.Array so it accepts EITHER a
// VARCHAR path OR a BLOB of media bytes — DeriveArgSpecs advertises it as
// arrow_type="any". The function body reads the raw column directly.
type inputArg struct {
	Input arrow.Array `vgi:"pos=0,const=false,doc=The media to probe: either a filesystem path to a media file or the raw media bytes themselves; ffprobe reads it to extract the requested metadata"`
}

// scalarFn is the per-row probe→value logic. Given a decoded ProbeResult it
// returns the typed value and whether it is present (false → SQL NULL).
//
// The generic emit machinery lives in mapProbe* below; each concrete scalar is
// just a name + a closure.

// scalarMeta carries the per-object discovery/description metadata (VGI112/113/
// 124/126/128) every scalar must surface. It is embedded in each typed scalar
// shape so the Metadata() builders share one tag-assembly path.
type scalarMeta struct {
	title    string
	llm      string
	md       string
	keywords string
	category string
}

// tags assembles the standard per-object tags for a scalar, all backed by
// scalars.go. category names an entry in the schema's vgi.categories registry.
func (m scalarMeta) tags() map[string]string {
	return objectTags(m.title, m.llm, m.md, m.keywords, "scalars.go", m.category)
}

// scalarStability is the stability advertised by every media scalar. Probing a
// file is CONSISTENT_WITHIN_QUERY: ffprobe returns the same result for the same
// path within a single query, but the result can change across queries if the
// underlying file is replaced. That is the honest classification — not VOLATILE
// (which would suppress all engine caching) and not CONSISTENT (the file is an
// external, mutable resource).
const scalarStability = vgi.StabilityConsistentWithinQuery

// stringScalar implements a VARCHAR-returning scalar over a probed input.
type stringScalar struct {
	scalarMeta
	name     string
	desc     string
	examples []vgi.CatalogExample
	get      func(r *ProbeResult) (string, bool)
}

func (f *stringScalar) Name() string { return f.name }
func (f *stringScalar) Metadata() vgi.FunctionMetadata {
	return vgi.FunctionMetadata{Description: f.desc, ReturnType: arrow.BinaryTypes.String, Examples: f.examples, Stability: scalarStability, Categories: []string{"media"}, Tags: scalarTags(f.scalarMeta, f.examples)}
}
func (f *stringScalar) OnBindTyped(_ *inputArg, _ *vgi.BindParams) (*vgi.BindResponse, error) {
	return vgi.BindResult(arrow.BinaryTypes.String)
}
func (f *stringScalar) ProcessTyped(ctx context.Context, _ *inputArg, params *vgi.ProcessParams, batch arrow.RecordBatch) (arrow.RecordBatch, error) {
	col := batch.Column(0)
	n := int(batch.NumRows())
	b := array.NewStringBuilder(allocator)
	defer b.Release()
	b.Reserve(n)
	for i := 0; i < n; i++ {
		r, err := probeRow(ctx, col, i)
		if err != nil {
			return nil, err
		}
		if v, ok := getOpt(r, f.get); ok {
			b.Append(v)
		} else {
			b.AppendNull()
		}
	}
	arr := b.NewArray()
	defer arr.Release()
	return array.NewRecordBatch(params.OutputSchema, []arrow.Array{arr}, int64(n)), nil
}

// int64Scalar implements a BIGINT-returning scalar over a probed input.
type int64Scalar struct {
	scalarMeta
	name     string
	desc     string
	examples []vgi.CatalogExample
	get      func(r *ProbeResult) (int64, bool)
}

func (f *int64Scalar) Name() string { return f.name }
func (f *int64Scalar) Metadata() vgi.FunctionMetadata {
	return vgi.FunctionMetadata{Description: f.desc, ReturnType: arrow.PrimitiveTypes.Int64, Examples: f.examples, Stability: scalarStability, Categories: []string{"media"}, Tags: scalarTags(f.scalarMeta, f.examples)}
}
func (f *int64Scalar) OnBindTyped(_ *inputArg, _ *vgi.BindParams) (*vgi.BindResponse, error) {
	return vgi.BindResult(arrow.PrimitiveTypes.Int64)
}
func (f *int64Scalar) ProcessTyped(ctx context.Context, _ *inputArg, params *vgi.ProcessParams, batch arrow.RecordBatch) (arrow.RecordBatch, error) {
	col := batch.Column(0)
	n := int(batch.NumRows())
	b := array.NewInt64Builder(allocator)
	defer b.Release()
	b.Reserve(n)
	for i := 0; i < n; i++ {
		r, err := probeRow(ctx, col, i)
		if err != nil {
			return nil, err
		}
		if v, ok := getOpt(r, f.get); ok {
			b.Append(v)
		} else {
			b.AppendNull()
		}
	}
	arr := b.NewArray()
	defer arr.Release()
	return array.NewRecordBatch(params.OutputSchema, []arrow.Array{arr}, int64(n)), nil
}

// int32Scalar implements an INTEGER-returning scalar over a probed input.
type int32Scalar struct {
	scalarMeta
	name     string
	desc     string
	examples []vgi.CatalogExample
	get      func(r *ProbeResult) (int32, bool)
}

func (f *int32Scalar) Name() string { return f.name }
func (f *int32Scalar) Metadata() vgi.FunctionMetadata {
	return vgi.FunctionMetadata{Description: f.desc, ReturnType: arrow.PrimitiveTypes.Int32, Examples: f.examples, Stability: scalarStability, Categories: []string{"media"}, Tags: scalarTags(f.scalarMeta, f.examples)}
}
func (f *int32Scalar) OnBindTyped(_ *inputArg, _ *vgi.BindParams) (*vgi.BindResponse, error) {
	return vgi.BindResult(arrow.PrimitiveTypes.Int32)
}
func (f *int32Scalar) ProcessTyped(ctx context.Context, _ *inputArg, params *vgi.ProcessParams, batch arrow.RecordBatch) (arrow.RecordBatch, error) {
	col := batch.Column(0)
	n := int(batch.NumRows())
	b := array.NewInt32Builder(allocator)
	defer b.Release()
	b.Reserve(n)
	for i := 0; i < n; i++ {
		r, err := probeRow(ctx, col, i)
		if err != nil {
			return nil, err
		}
		if v, ok := getOpt(r, f.get); ok {
			b.Append(v)
		} else {
			b.AppendNull()
		}
	}
	arr := b.NewArray()
	defer arr.Release()
	return array.NewRecordBatch(params.OutputSchema, []arrow.Array{arr}, int64(n)), nil
}

// float64Scalar implements a DOUBLE-returning scalar over a probed input.
type float64Scalar struct {
	scalarMeta
	name     string
	desc     string
	examples []vgi.CatalogExample
	get      func(r *ProbeResult) (float64, bool)
}

func (f *float64Scalar) Name() string { return f.name }
func (f *float64Scalar) Metadata() vgi.FunctionMetadata {
	return vgi.FunctionMetadata{Description: f.desc, ReturnType: arrow.PrimitiveTypes.Float64, Examples: f.examples, Stability: scalarStability, Categories: []string{"media"}, Tags: scalarTags(f.scalarMeta, f.examples)}
}
func (f *float64Scalar) OnBindTyped(_ *inputArg, _ *vgi.BindParams) (*vgi.BindResponse, error) {
	return vgi.BindResult(arrow.PrimitiveTypes.Float64)
}
func (f *float64Scalar) ProcessTyped(ctx context.Context, _ *inputArg, params *vgi.ProcessParams, batch arrow.RecordBatch) (arrow.RecordBatch, error) {
	col := batch.Column(0)
	n := int(batch.NumRows())
	b := array.NewFloat64Builder(allocator)
	defer b.Release()
	b.Reserve(n)
	for i := 0; i < n; i++ {
		r, err := probeRow(ctx, col, i)
		if err != nil {
			return nil, err
		}
		if v, ok := getOpt(r, f.get); ok {
			b.Append(v)
		} else {
			b.AppendNull()
		}
	}
	arr := b.NewArray()
	defer arr.Release()
	return array.NewRecordBatch(params.OutputSchema, []arrow.Array{arr}, int64(n)), nil
}

// getOpt applies get to r, returning (zero, false) when r is nil (NULL input or
// probe failure) so every accessor closure can assume a non-nil result.
func getOpt[T any](r *ProbeResult, get func(*ProbeResult) (T, bool)) (T, bool) {
	if r == nil {
		var zero T
		return zero, false
	}
	return get(r)
}

// ex builds a single catalog-qualified example for a scalar. The SQL is always
// qualified as media.main.<fn>(...) so the metadata linter sees a fully
// resolvable, copy-pasteable query referencing the function by name.
func ex(sql, desc string) []vgi.CatalogExample {
	return []vgi.CatalogExample{{SQL: sql, Description: desc}}
}

// scalarTags assembles the per-object tags for a scalar and folds in the
// described example_queries carrier (VGI515). The native FunctionMetadata.Examples
// list survives the community extension's duckdb_functions().examples column but
// DROPS each example's description, so VGI515 requires the descriptions to be
// republished as a byte-stable JSON [{description, sql}] list in a dedicated tag.
func scalarTags(m scalarMeta, examples []vgi.CatalogExample) map[string]string {
	t := m.tags()
	t["vgi.example_queries"] = exampleQueriesJSON(examples)
	return t
}

// exampleQueriesJSON serializes a CatalogExample list as the described-example
// JSON VGI515 expects: a list of objects each with a non-empty "description" and
// "sql" (in that key order).
func exampleQueriesJSON(exs []vgi.CatalogExample) string {
	type described struct {
		Description string `json:"description"`
		SQL         string `json:"sql"`
	}
	out := make([]described, 0, len(exs))
	for _, e := range exs {
		out = append(out, described{Description: e.Description, SQL: e.SQL})
	}
	b, err := jsonMarshal(out)
	if err != nil {
		return "[]"
	}
	return b
}

// registerScalars registers every scalar function on the worker.
func registerScalars(w *vgi.Worker) {
	// --- container-level ---
	w.RegisterScalar(vgi.AsScalarFunction[inputArg](&stringScalar{
		scalarMeta: scalarMeta{
			title: "Container Format Name",
			llm: "Return the container/wrapper format name of a media file, as reported by " +
				"ffprobe's format_name (e.g. 'mov,mp4,m4a,3gp,3g2,mj2' for an MP4, 'matroska,webm' " +
				"for an MKV, 'wav' for a WAV). The argument is a file path (`VARCHAR`) or media bytes " +
				"(`BLOB`); returns NULL when the input is not decodable media.",
			md: "Return the container format name of a media file, e.g. " +
				"`media_format('/clips/intro.mp4')` → `mov,mp4,m4a,3gp,3g2,mj2`.",
			keywords: "media format, container format, format_name, wrapper, mp4, mkv, wav, mov, container type",
			category: "container",
		},
		name: "media_format", desc: "Container format name (format_name), e.g. 'mov,mp4,m4a,3gp,3g2,mj2'",
		examples: ex(
			"SELECT media.main.media_format('/clips/intro.mp4');",
			"Return the container format name of a media file given its path.",
		),
		get: func(r *ProbeResult) (string, bool) {
			if r.Format.FormatName == "" {
				return "", false
			}
			return r.Format.FormatName, true
		},
	}))
	w.RegisterScalar(vgi.AsScalarFunction[inputArg](&float64Scalar{
		scalarMeta: scalarMeta{
			title: "Media Duration Seconds",
			llm: "Return the total playback duration of a media file in seconds (`DOUBLE`), taken " +
				"from the container format header. The argument is a file path (`VARCHAR`) or media " +
				"bytes (`BLOB`); returns NULL when ffprobe cannot determine a duration.",
			md: "Return the duration of a media file in seconds, e.g. " +
				"`duration('/clips/intro.mp4')` → `12.5`.",
			keywords: "duration, length, runtime, seconds, playback time, how long, media length",
			category: "container",
		},
		name: "duration", desc: "Container duration in seconds",
		examples: ex(
			"SELECT media.main.duration('/clips/intro.mp4');",
			"Return the duration of a media file in seconds.",
		),
		get: func(r *ProbeResult) (float64, bool) { return r.Duration() },
	}))
	w.RegisterScalar(vgi.AsScalarFunction[inputArg](&int64Scalar{
		scalarMeta: scalarMeta{
			title: "Overall Bit Rate",
			llm: "Return the overall container bit rate of a media file in bits per second " +
				"(`BIGINT`), as reported by ffprobe's format bit_rate. The argument is a file path " +
				"(`VARCHAR`) or media bytes (`BLOB`); returns NULL when the bit rate is unknown.",
			md: "Return the overall container bit rate in bits per second, e.g. " +
				"`bitrate('/clips/intro.mp4')` → `2500000`.",
			keywords: "bitrate, bit rate, bits per second, bps, data rate, quality, encoding rate",
			category: "container",
		},
		name: "bitrate", desc: "Container bit rate in bits per second",
		examples: ex(
			"SELECT media.main.bitrate('/clips/intro.mp4');",
			"Return the overall container bit rate in bits per second.",
		),
		get: func(r *ProbeResult) (int64, bool) { return r.BitRate() },
	}))
	w.RegisterScalar(vgi.AsScalarFunction[inputArg](&int64Scalar{
		scalarMeta: scalarMeta{
			title: "Media File Size Bytes",
			llm: "Return the size of a media file in bytes (`BIGINT`), as reported by ffprobe's " +
				"format size field. The argument is a file path (`VARCHAR`) or media bytes (`BLOB`); " +
				"returns NULL when ffprobe does not report a size (e.g. some piped `BLOB` inputs).",
			md: "Return the size of a media file in bytes, e.g. " +
				"`media_size('/clips/intro.mp4')` → `4194304`.",
			keywords: "size, file size, bytes, media size, length in bytes, byte count, file weight",
			category: "container",
